INSERT IGNORE INTO `page_definition` (`id`, `tenant_id`, `code`, `title`, `description`, `category`, `current_version_id`, `status`, `created_at`, `created_by`, `updated_at`) VALUES (1,-1,'aria:front-gate-create','Front-Gate Intake','Gate-pass creation flow for inbound tankers','M10',358,'PUBLISHED','2026-06-07 08:10:58',NULL,'2026-07-17 05:40:35'),
(2,-1,'aria:parking-scan','Parking-Bay Scan','Scan GP QR + assign bay','M10',2,'PUBLISHED','2026-06-07 08:10:58',NULL,'2026-07-17 05:40:35'),
(3,-1,'aria:dispatch-vehicle-entry','Dispatch Vehicle Entry','Vehicle entry review — match to PO/SO/RN, identify item category (RM oil / packing carton / FG / return / inter-unit), decide approve / needs-manager / reject.','M10',3,'PUBLISHED','2026-06-07 08:10:58',NULL,'2026-07-17 05:40:35'),
(4,-1,'aria:qc-approval','QC Approval','Item-category-aware QC. Oil receipts get density/FFA/colour, packing material gets print/dimensions/integrity, FG/returns get seal/label/expiry checks.','M10',4,'PUBLISHED','2026-06-07 08:10:58',NULL,'2026-07-17 05:40:35'),
(5,-1,'aria:weighment-capture','Weighment Capture','Truck weighment — loaded on entry, empty on exit. Variance routes to manager. One reading per direction (not oil W1/W2/W3 sequence).','M10',5,'PUBLISHED','2026-06-07 08:10:58',NULL,'2026-07-17 05:40:35'),
(6,-1,'aria:supervisor-unloading','Unloading Supervisor','Packed-goods / Raw-material receipt at the godown. Count by item, allocate to bin, capture damages, confirm. Not for bulk oil tank pumping.','M10',6,'PUBLISHED','2026-06-07 08:10:58',NULL,'2026-07-17 05:40:35'),
(7,-1,'aria:manager-approval-inbox','Manager Approval Inbox','Vehicles awaiting manager decision — quantity variance, weight discrepancy (W2 vs W3), missing PO, return-stock variance, or QC rejected. Shows full decision context per row; one-click Approve/Reject/Print.','M10',7,'PUBLISHED','2026-06-07 08:10:58',NULL,'2026-07-17 05:40:35'),
(8,-1,'aria:vendor-list','Vendors','Vendor master per Tally Prime — code, name, GSTIN+PAN, bank a/c+IFSC, pay terms, credit limit, default item category, MSME regn. Used in PO, payments, GST.','Master',8,'PUBLISHED','2026-06-07 12:57:36',NULL,'2026-07-17 05:40:35'),
(9,-1,'aria:vendor-detail','Vendor Detail','Vendor detail with tabs (Schema V2 demo)','Master',9,'PUBLISHED','2026-06-07 12:57:36',NULL,'2026-07-17 05:40:35'),
(10,-1,'aria:m11-integrations-list','Integration Instances','Plug-and-play connectors EARMS uses to talk to MSG91 SMS, SMTP email, Tally TDL, NIC E-Invoice, Modbus weighbridges, MQTT conveyors, Excel imports, label printers, SAP. Drop credentials in to flip from dryRun → live. Click Ping to test connectivity; click Edit Config to set host/port/secrets.','M11',10,'PUBLISHED','2026-06-07 17:37:24',NULL,'2026-07-17 05:40:35'),
(11,-1,'aria:recent-gate-passes','Recent Gate Passes','All gate passes — search by vehicle, driver, or GP number; click any row for the full audit trail.','M10',11,'PUBLISHED','2026-06-08 06:51:42',NULL,'2026-07-17 05:40:35'),
(12,-1,'aria:driver-master','Drivers','Driver master per Tally / Marg ERP — name, mobile, DL+expiry+class, default vehicle, salary type, status. Mobile + DL required.','Master',12,'PUBLISHED','2026-06-08 07:02:55',NULL,'2026-07-17 05:40:35'),
(14,-1,'aria:workflow-activity','Workflow Activity Trail','Every workflow event in the platform — start, transition, page-submission, cancel, error. Use the kind filter to focus on a single category; click a row to see the SpEL guard payload that drove the decision.','M0',14,'PUBLISHED','2026-06-08 07:06:44',NULL,'2026-07-17 05:40:35'),
(15,-1,'aria:vehicle-master','Vehicles','Vehicle master per SAP Fleet — registration, type, make/model/year, tare+capacity, RC/Insurance/FC/Permit/PUC expiries, GPS device. Expiry traffic-lights flag renewals.','Master',15,'PUBLISHED','2026-06-08 07:08:48',NULL,'2026-07-17 05:40:35'),
(16,-1,'aria:gate-master','Gates','Gates configured for the plant — link gate code to flow type + active weighbridge.','Master',16,'PUBLISHED','2026-06-08 07:08:48',NULL,'2026-07-17 05:40:35'),
(17,-1,'aria:weighbridge-master','Weighbridges','Weighbridge master — code, capacity, make/model/serial, TCP IP for live feed, calibration date + next due. Calibration expiry triggers compliance alert.','Master',17,'PUBLISHED','2026-06-08 07:12:53',NULL,'2026-07-17 05:40:35'),
(18,-1,'aria:parking-bay-master','Parking Bays','Parking bay grid — assigned vehicles + dwell time. Configurable capacity per bay.','Master',18,'PUBLISHED','2026-06-08 07:12:53',NULL,'2026-07-17 05:40:35'),
(19,-1,'aria:lane-master','Lanes','Inbound/outbound lanes per gate.','Master',19,'PUBLISHED','2026-06-08 07:12:53',NULL,'2026-07-17 05:40:35'),
(20,-1,'aria:gate-pass-closure','Close Gate Pass','Front-gate exit stamp + final verification.','M10',616,'PUBLISHED','2026-06-08 07:17:15',NULL,'2026-07-17 05:40:35'),
(21,-1,'aria:plantowner-dashboard','Plantowner Dashboard','Live KPIs across dispatch, masters, workflow.','Dashboard',21,'PUBLISHED','2026-06-08 07:19:39',NULL,'2026-07-17 05:40:35'),
