INSERT IGNORE INTO `page_version` (`id`, `page_id`, `version`, `status`, `body_json`, `rationale`, `published_at`, `published_by`, `created_at`) VALUES (2,2,1,'PUBLISHED','{\"schemaVersion\": \"1.0.0\", \"slug\": \"aria:parking-scan\", \"title\": \"Parking-Bay Scan\", \"status\": \"published\", \"version\": 1, \"roles\": [\"ParkingSecurity\", \"Dispatch\", \"Manager\", \"TenantAdmin\"], \"dataSources\": [], \"streams\": [], \"layout\": {\"type\": \"Grid\", \"id\": \"root\", \"props\": {\"columns\": 12, \"gap\": 16}, \"children\": [{\"type\": \"Section\", \"id\": \"sec-scan\", \"props\": {\"title\": \"Scan / Select Gate-Pass\", \"span\": 12, \"subtitle\": \"Tap Scan to use the camera, or pick the Gate Pass # from the list — vehicle, flow and loading context fill in automatically.\"}, \"children\": [{\"type\": \"QrScan\", \"id\": \"scan-gp\", \"props\": {\"label\": \"Tap to Scan\", \"targetField\": \"gpNumber\", \"manualFallback\": true}}, {\"type\": \"Form\", \"id\": \"form-scan\", \"props\": {\"submitLabel\": \"\"}, \"bindings\": {\"fields\": [{\"name\": \"gpNumber\", \"label\": \"Gate Pass #\", \"type\": \"select\", \"required\": true, \"placeholder\": \"Scan above or select Gate Pass #\", \"optionsSource\": {\"type\": \"entity\", \"entity\": \"GatePass\", \"lookupType\": \"gpNumbers\", \"valueField\": \"gp_number\", \"labelField\": \"gp_number\"}, \"onChangeFill\": {\"vehicleNo\": \"vehicle_no\", \"flowVariantCode\": \"flow_variant_code\", \"loadingType\": \"loading_type\", \"instanceId\": \"workflow_instance_id\"}}, {\"name\": \"vehicleNo\", \"label\": \"Vehicle Number\", \"type\": \"text\", \"disabled\": true}, {\"name\": \"flowVariantCode\", \"label\": \"Flow Variant\", \"type\": \"text\", \"disabled\": true}, {\"name\": \"loadingType\", \"label\": \"Loading Type\", \"type\": \"text\", \"disabled\": true}, {\"name\": \"instanceId\", \"label\": \"Workflow Instance\", \"type\": \"text\", \"disabled\": true}]}}]}, {\"type\": \"Section\", \"id\": \"sec-submit\", \"props\": {\"span\": 12}, \"children\": [{\"type\": \"WorkflowActionButton\", \"id\": \"btn-confirm\", \"props\": {\"action\": \"workflow.transition\", \"label\": \"Confirm\", \"instanceId\": \"{{form.instanceId}}\", \"variant\": \"primary\"}}]}]}}',NULL,'2026-06-07 08:10:58',NULL,'2026-06-07 08:10:58'),
(3,3,1,'PUBLISHED','{\"schemaVersion\": \"1.0.0\", \"slug\": \"aria:dispatch-vehicle-entry\", \"title\": \"Dispatch Vehicle Entry\", \"status\": \"published\", \"version\": 1, \"roles\": [\"Dispatch\", \"Manager\", \"TenantAdmin\"], \"dataSources\": [], \"streams\": [], \"layout\": {\"type\": \"Grid\", \"id\": \"root\", \"props\": {\"columns\": 12, \"gap\": 16}, \"children\": [{\"type\": \"Section\", \"id\": \"sec-po\", \"props\": {\"title\": \"Reference Match\", \"span\": 12, \"subtitle\": \"For inbound: match to open PO / GRN draft. For outbound: match to SO / customer order. No reference → manager approval.\"}, \"children\": [{\"type\": \"Form\", \"id\": \"form-po\", \"props\": {\"submitLabel\": \"\"}, \"bindings\": {\"fields\": [{\"name\": \"gp_number\", \"label\": \"Gate Pass # (auto)\", \"type\": \"text\", \"required\": true, \"readOnly\": true}, {\"name\": \"reference_no\", \"label\": \"PO / SO / RN Reference #\", \"type\": \"text\", \"helperText\": \"Match validates: party, item, qty, dispatch date\"}, {\"name\": \"reference_status\", \"label\": \"Match Status\", \"type\": \"select\", \"readOnly\": true, \"options\": [\"MATCHED\", \"PARTIAL\", \"NO_MATCH\", \"NO_REF\"]}, {\"name\": \"no_ref_reason\", \"label\": \"No-reference reason (if none)\", \"type\": \"textarea\", \"rows\": 2, \"helperText\": \"Triggers manager approval before vehicle proceeds\"}]}}]}, {\"type\": \"Section\", \"id\": \"sec-party\", \"props\": {\"title\": \"Source / Destination Party\", \"span\": 12}, \"children\": [{\"type\": \"Form\", \"id\": \"form-party\", \"props\": {\"submitLabel\": \"\"}, \"bindings\": {\"fields\": [{\"name\": \"party_name\", \"label\": \"Party Name (Vendor / Customer)\", \"type\": \"text\", \"required\": true}, {\"name\": \"party_doc_no\", \"label\": \"Vendor Invoice / Customer DC No.\", \"type\": \"text\"}, {\"name\": \"party_qty\", \"label\": \"Document Quantity\", \"type\": \"number\"}, {\"name\": \"item_category\", \"label\": \"Item Category\", \"type\": \"select\", \"required\": true, \"options\": [{\"label\": \"Raw Material — bulk oil (drum / can / bottled)\", \"value\": \"RM_OIL\"}, {\"label\": \"Raw Material — jaggery / agarbatti raw\", \"value\": \"RM_OTHER\"}, {\"label\": \"Packing Material — cartons / cases\", \"value\": \"PACK_CARTON\"}, {\"label\": \"Packing Material — bottles / cans\", \"value\": \"PACK_BOTTLE\"}, {\"label\": \"Packing Material — caps / labels / inner liners\", \"value\": \"PACK_SMALL\"}, {\"label\": \"Finished Goods — packed for dispatch\", \"value\": \"FG\"}, {\"label\": \"Return Stock — FG / packing returned\", \"value\": \"RETURN\"}, {\"label\": \"Inter-Unit Transfer\", \"value\": \"INTERUNIT\"}]}]}}]}, {\"type\": \"Section\", \"id\": \"sec-dfo\", \"props\": {\"title\": \"Dispatch Officer Decision\", \"span\": 12}, \"children\": [{\"type\": \"Form\", \"id\": \"form-dfo\", \"props\": {\"submitLabel\": \"\"}, \"bindings\": {\"fields\": [{\"name\": \"dispatch_officer_id\", \"label\": \"Officer (auto-fill)\", \"type\": \"text\", \"readOnly\": true}, {\"name\": \"entry_remarks\", \"label\": \"Remarks (optional)\", \"type\": \"textarea\", \"rows\": 2}, {\"name\": \"status\", \"label\": \"Decision\", \"type\": \"select\", \"required\": true, \"options\": [{\"label\": \"✓ APPROVED — proceed to QC queue\", \"value\": \"APPROVED\"}, {\"label\": \"⚠ NEEDS MANAGER (no ref / party mismatch)\", \"value\": \"NEEDS_MANAGER\"}, {\"label\": \"✗ REJECTED — vehicle to be turned back\", \"value\": \"REJECTED\"}]}]}}]}, {\"type\": \"Section\", \"id\": \"sec-submit\", \"props\": {\"span\": 12}, \"children\": [{\"type\": \"WorkflowActionButton\", \"id\": \"btn-q\", \"props\": {\"action\": \"workflow.transition\", \"label\": \"Queue Vehicle for QC\", \"variant\": \"primary\"}}]}]}}',NULL,'2026-06-07 08:10:58',NULL,'2026-06-07 08:10:58'),
(4,4,1,'PUBLISHED','{\"schemaVersion\": \"1.0.0\", \"slug\": \"aria:qc-approval\", \"title\": \"QC Approval\", \"status\": \"published\", \"version\": 1, \"roles\": [\"QC\", \"Manager\", \"TenantAdmin\"], \"dataSources\": [], \"streams\": [], \"layout\": {\"type\": \"Grid\", \"id\": \"root\", \"props\": {\"columns\": 12, \"gap\": 16}, \"children\": [{\"type\": \"Section\", \"id\": \"sec-id\", \"props\": {\"title\": \"Sample Identification\", \"span\": 12}, \"children\": [{\"type\": \"Form\", \"id\": \"form-id\", \"props\": {\"submitLabel\": \"\"}, \"bindings\": {\"fields\": [{\"name\": \"gp_number\", \"label\": \"Gate Pass # (from inbox)\", \"type\": \"text\", \"required\": true}, {\"name\": \"item_category\", \"label\": \"Item Category (auto-fill from dispatch entry)\", \"type\": \"select\", \"required\": true, \"options\": [{\"label\": \"RM Oil — bottled / canned / drum\", \"value\": \"RM_OIL\"}, {\"label\": \"RM Other — jaggery / agarbatti raw\", \"value\": \"RM_OTHER\"}, {\"label\": \"Packing — cartons / cases\", \"value\": \"PACK_CARTON\"}, {\"label\": \"Packing — bottles / cans\", \"value\": \"PACK_BOTTLE\"}, {\"label\": \"Packing — caps / labels\", \"value\": \"PACK_SMALL\"}, {\"label\": \"FG — packed for dispatch\", \"value\": \"FG\"}, {\"label\": \"Return Stock\", \"value\": \"RETURN\"}]}, {\"name\": \"sample_jar_id\", \"label\": \"Sample / Sample Lot ID\", \"type\": \"text\", \"required\": true, \"placeholder\": \"SAMPLE-2026-0617\"}, {\"name\": \"qc_officer_id\", \"label\": \"QC Officer (auto-fill)\", \"type\": \"text\", \"readOnly\": true}]}}]}, {\"type\": \"Section\", \"id\": \"sec-oil\", \"props\": {\"title\": \"Oil Parameters (only if item category = RM Oil / FG)\", \"span\": 12, \"subtitle\": \"Skip this section if the receipt is packing material / return / non-oil.\"}, \"children\": [{\"type\": \"Form\", \"id\": \"form-oil\", \"props\": {\"submitLabel\": \"\"}, \"bindings\": {\"fields\": [{\"name\": \"density_kgl\", \"label\": \"Density (kg/L) — spec 0.910–0.930 for groundnut\", \"type\": \"number\"}, {\"name\": \"ffa_pct\", \"label\": \"Free Fatty Acid (%) — spec ≤ 0.20\", \"type\": \"number\"}, {\"name\": \"colour_rating\", \"label\": \"Colour vs reference\", \"type\": \"select\", \"options\": [{\"label\": \"Golden / Pale yellow — Pass\", \"value\": \"PASS_GOLDEN\"}, {\"label\": \"Light orange — Pass\", \"value\": \"PASS_ORANGE\"}, {\"label\": \"Dark brown — Fail\", \"value\": \"FAIL_DARK\"}, {\"label\": \"Cloudy — Fail\", \"value\": \"FAIL_CLOUDY\"}]}, {\"name\": \"temperature_c\", \"label\": \"Temperature (°C) — spec ≤ 35\", \"type\": \"number\"}]}}]}, {\"type\": \"Section\", \"id\": \"sec-pack\", \"props\": {\"title\": \"Packing-Material Parameters (only if Packing)\", \"span\": 12, \"subtitle\": \"Skip if not packing material.\"}, \"children\": [{\"type\": \"Form\", \"id\": \"form-pack\", \"props\": {\"submitLabel\": \"\"}, \"bindings\": {\"fields\": [{\"name\": \"print_quality\", \"label\": \"Print quality (labels / cartons)\", \"type\": \"select\", \"options\": [\"PASS\", \"PASS_MINOR\", \"FAIL_PRINT\"]}, {\"name\": \"dimensional_check\", \"label\": \"Dimensions match spec? (±2 mm)\", \"type\": \"select\", \"options\": [\"PASS\", \"MARGINAL\", \"FAIL\"]}, {\"name\": \"bottle_integrity\", \"label\": \"Bottle integrity — burst pressure / cap fit\", \"type\": \"select\", \"options\": [\"PASS\", \"PARTIAL\", \"FAIL_CRACK\", \"FAIL_CAP_FIT\"]}, {\"name\": \"carton_strength\", \"label\": \"Carton strength — drop test\", \"type\": \"select\", \"options\": [\"PASS\", \"MARGINAL\", \"FAIL\"]}]}}]}, {\"type\": \"Section\", \"id\": \"sec-fg\", \"props\": {\"title\": \"FG / Return Inspection (only if FG / Return)\", \"span\": 12, \"subtitle\": \"Skip if not FG or return.\"}, \"children\": [{\"type\": \"Form\", \"id\": \"form-fg\", \"props\": {\"submitLabel\": \"\"}, \"bindings\": {\"fields\": [{\"name\": \"seal_intact\", \"label\": \"Seal intact?\", \"type\": \"select\", \"options\": [\"YES\", \"BROKEN\", \"MISSING\"]}, {\"name\": \"label_match\", \"label\": \"Label matches SKU master?\", \"type\": \"select\", \"options\": [\"YES\", \"BATCH_MISMATCH\", \"EXPIRY_MISMATCH\", \"MRP_MISMATCH\"]}, {\"name\": \"batch_expiry_check\", \"label\": \"Within shelf life?\", \"type\": \"select\", \"options\": [\"YES\", \"NEAR_EXPIRY\", \"EXPIRED\"]}]}}]}, {\"type\": \"Section\", \"id\": \"sec-photo\", \"props\": {\"title\": \"Photo + Seal\", \"span\": 12}, \"children\": [{\"type\": \"Form\", \"id\": \"form-ph\", \"props\": {\"submitLabel\": \"\"}, \"bindings\": {\"fields\": [{\"name\": \"sample_photo\", \"label\": \"Sample Photo\", \"type\": \"file\", \"accept\": \"image/*\"}, {\"name\": \"seal_unlock_no\", \"label\": \"Seal Unlock #\", \"type\": \"text\"}, {\"name\": \"qc_notes\", \"label\": \"Notes\", \"type\": \"textarea\", \"rows\": 3}]}}]}, {\"type\": \"Section\", \"id\": \"sec-dec\", \"props\": {\"title\": \"Decision\", \"span\": 12}, \"children\": [{\"type\": \"Form\", \"id\": \"form-dec\", \"props\": {\"submitLabel\": \"\"}, \"bindings\": {\"fields\": [{\"name\": \"status\", \"label\": \"QC Decision\", \"type\": \"select\", \"required\": true, \"options\": [{\"label\": \"✓ APPROVED — all parameters pass\", \"value\": \"APPROVED\"}, {\"label\": \"✓ APPROVED with notes (managed exception)\", \"value\": \"APPROVED_NOTES\"}, {\"label\": \"✗ REJECTED — see notes / debit vendor\", \"value\": \"REJECTED\"}]}]}, \"props\": {}}, {\"type\": \"WorkflowActionButton\", \"id\": \"btn-qc\", \"props\": {\"action\": \"workflow.transition\", \"label\": \"Submit QC Decision\", \"variant\": \"primary\"}}]}]}}',NULL,'2026-06-07 08:10:58',NULL,'2026-06-07 08:10:58'),
(5,5,1,'PUBLISHED','{\"schemaVersion\": \"1.0.0\", \"slug\": \"aria:weighment-capture\", \"title\": \"Weighment Capture\", \"status\": \"published\", \"version\": 1, \"roles\": [\"WeighmentOfficer\", \"Manager\", \"TenantAdmin\"], \"dataSources\": [], \"streams\": [], \"layout\": {\"type\": \"Grid\", \"id\": \"root\", \"props\": {\"columns\": 12, \"gap\": 16}, \"children\": [{\"type\": \"Section\", \"id\": \"sec-ctx\", \"props\": {\"title\": \"Vehicle & Weighbridge\", \"span\": 12, \"subtitle\": \"One weighment per direction. Loaded weight on entry, empty on exit; difference = quantity received/dispatched.\"}, \"children\": [{\"type\": \"Form\", \"id\": \"form-ctx\", \"props\": {\"submitLabel\": \"\"}, \"bindings\": {\"fields\": [{\"name\": \"gp_number\", \"label\": \"Gate Pass # (from queue)\", \"type\": \"text\", \"required\": true, \"readOnly\": true}, {\"name\": \"vehicle_no\", \"label\": \"Vehicle (auto-fill)\", \"type\": \"text\", \"readOnly\": true}, {\"name\": \"weighbridge_code\", \"label\": \"Weighbridge\", \"type\": \"select\", \"required\": true, \"options\": [{\"label\": \"WB-1 (Main Gate, 60T)\", \"value\": \"WB-1\"}, {\"label\": \"WB-2 (Dispatch, 40T)\", \"value\": \"WB-2\"}]}, {\"name\": \"weighment_date\", \"label\": \"Date\", \"type\": \"date\", \"required\": true}, {\"name\": \"entry_time\", \"label\": \"Entry Time\", \"type\": \"time\", \"required\": true}, {\"name\": \"weight_officer\", \"label\": \"Weighment Officer Name\", \"type\": \"text\", \"required\": true}]}}]}, {\"type\": \"Section\", \"id\": \"sec-w\", \"props\": {\"title\": \"Reading\", \"span\": 12, \"subtitle\": \"Live feed from the weighbridge controller. Press Capture to lock the reading.\"}, \"children\": [{\"type\": \"Form\", \"id\": \"form-w\", \"props\": {\"submitLabel\": \"\"}, \"bindings\": {\"fields\": [{\"name\": \"direction\", \"label\": \"Weighment\", \"type\": \"select\", \"required\": true, \"options\": [{\"label\": \"Loaded (entry — full)\", \"value\": \"LOADED\"}, {\"label\": \"Empty (exit — tare check)\", \"value\": \"EMPTY\"}, {\"label\": \"Re-check (only if discrepancy)\", \"value\": \"RECHECK\"}]}, {\"name\": \"live_reading_display\", \"label\": \"Live Reading\", \"type\": \"text\", \"readOnly\": true, \"helperText\": \"Locked while stabilising — wait for the green tick on the controller\"}, {\"name\": \"gross_kg\", \"label\": \"Gross Weight (kg)\", \"type\": \"number\", \"required\": true}, {\"name\": \"tare_kg\", \"label\": \"Tare (kg) — from vehicle master or this empty reading\", \"type\": \"number\"}, {\"name\": \"net_kg\", \"label\": \"Net (kg) — auto Gross − Tare\", \"type\": \"number\", \"readOnly\": true}, {\"name\": \"expected_kg\", \"label\": \"Expected (kg) — from PO / SO\", \"type\": \"number\", \"readOnly\": true}, {\"name\": \"variance_kg\", \"label\": \"Variance (kg) — auto\", \"type\": \"number\", \"readOnly\": true}, {\"name\": \"within_tolerance\", \"label\": \"Within Tolerance?\", \"type\": \"select\", \"required\": true, \"options\": [{\"label\": \"YES — proceed\", \"value\": \"YES\"}, {\"label\": \"NO — route to manager\", \"value\": \"NO\"}]}]}}]}, {\"type\": \"Section\", \"id\": \"sec-photo\", \"props\": {\"title\": \"Photo Evidence\", \"span\": 12}, \"children\": [{\"type\": \"Form\", \"id\": \"form-photo\", \"props\": {\"submitLabel\": \"\"}, \"bindings\": {\"fields\": [{\"name\": \"wb_display_photo\", \"label\": \"Weighbridge Display Photo\", \"type\": \"file\", \"accept\": \"image/*\"}, {\"name\": \"vehicle_photo\", \"label\": \"Vehicle on Bridge Photo\", \"type\": \"file\", \"accept\": \"image/*\"}, {\"name\": \"notes\", \"label\": \"Notes (any anomaly)\", \"type\": \"textarea\", \"rows\": 2}]}}]}, {\"type\": \"Section\", \"id\": \"sec-submit\", \"props\": {\"span\": 12}, \"children\": [{\"type\": \"WorkflowActionButton\", \"id\": \"btn-cap\", \"props\": {\"action\": \"workflow.transition\", \"label\": \"Capture & Save Weighment\", \"variant\": \"primary\"}}]}]}}',NULL,'2026-06-07 08:10:58',NULL,'2026-06-07 08:10:58'),
(6,6,1,'PUBLISHED','{\"schemaVersion\": \"1.0.0\", \"slug\": \"aria:supervisor-unloading\", \"title\": \"Unloading Supervisor — Goods Receipt\", \"status\": \"published\", \"version\": 1, \"roles\": [\"UnloadingSupervisor\", \"StoreKeeper\", \"Manager\", \"TenantAdmin\"], \"dataSources\": [], \"streams\": [], \"layout\": {\"type\": \"Grid\", \"id\": \"root\", \"props\": {\"columns\": 12, \"gap\": 16}, \"children\": [{\"type\": \"Section\", \"id\": \"sec-ctx\", \"props\": {\"title\": \"Vehicle & Reference\", \"span\": 12, \"subtitle\": \"Auto-fills from the gate pass assigned to your queue. Confirm before counting goods.\"}, \"children\": [{\"type\": \"Form\", \"id\": \"form-ctx\", \"props\": {\"submitLabel\": \"\"}, \"bindings\": {\"fields\": [{\"name\": \"gp_number\", \"label\": \"Gate Pass # (from queue)\", \"type\": \"text\", \"required\": true, \"readOnly\": true}, {\"name\": \"vehicle_no\", \"label\": \"Vehicle\", \"type\": \"text\", \"readOnly\": true}, {\"name\": \"flow_kind\", \"label\": \"Receipt Type\", \"type\": \"select\", \"required\": true, \"options\": [{\"label\": \"Raw Material — bottled / canned / drum (inbound from vendor)\", \"value\": \"RM_INBOUND\"}, {\"label\": \"Packing Material — cartons / bottles / caps / labels (inbound)\", \"value\": \"PACKING_INBOUND\"}, {\"label\": \"Return Stock — FG returned by customer\", \"value\": \"RETURN_INBOUND\"}, {\"label\": \"Inter-Unit Transfer In\", \"value\": \"INTER_UNIT_IN\"}]}, {\"name\": \"reference_no\", \"label\": \"Reference (PO# / GRN# / RN#)\", \"type\": \"text\", \"required\": true}]}}]}, {\"type\": \"Section\", \"id\": \"sec-goods\", \"props\": {\"title\": \"Goods Receipt — Count by Item\", \"span\": 12, \"subtitle\": \"Verify item code, count cases physically as you unload. Repeat the block for each item in the truck.\"}, \"children\": [{\"type\": \"Form\", \"id\": \"form-goods\", \"props\": {\"submitLabel\": \"\"}, \"bindings\": {\"fields\": [{\"name\": \"item_code\", \"label\": \"Item / SKU Code\", \"type\": \"text\", \"required\": true, \"placeholder\": \"GIN-1L-IDH\", \"helperText\": \"Scan barcode or pick from SKU master\"}, {\"name\": \"item_description\", \"label\": \"Item Name (auto-fill)\", \"type\": \"text\", \"readOnly\": true}, {\"name\": \"uom\", \"label\": \"UOM\", \"type\": \"select\", \"required\": true, \"options\": [{\"label\": \"Cases\", \"value\": \"CASE\"}, {\"label\": \"Bottles\", \"value\": \"BOTTLE\"}, {\"label\": \"Bundles\", \"value\": \"BUNDLE\"}, {\"label\": \"Pallets\", \"value\": \"PALLET\"}, {\"label\": \"Bags\", \"value\": \"BAG\"}, {\"label\": \"Pieces\", \"value\": \"NOS\"}, {\"label\": \"Drums\", \"value\": \"DRUM\"}, {\"label\": \"Kilograms\", \"value\": \"KG\"}, {\"label\": \"Litres\", \"value\": \"L\"}]}, {\"name\": \"received_qty\", \"label\": \"Quantity Received\", \"type\": \"number\", \"required\": true, \"helperText\": \"Counted physically as cases / bottles came off the truck\"}, {\"name\": \"invoice_qty\", \"label\": \"Invoice Qty (from PO / vendor invoice)\", \"type\": \"number\", \"helperText\": \"System flags variance if Received ≠ Invoice\"}, {\"name\": \"batch_no\", \"label\": \"Batch / Lot Number\", \"type\": \"text\", \"placeholder\": \"B26-0421-A\"}, {\"name\": \"mfg_date\", \"label\": \"Manufacturing Date\", \"type\": \"date\"}, {\"name\": \"expiry_date\", \"label\": \"Expiry / Best-Before Date\", \"type\": \"date\"}]}}]}, {\"type\": \"Section\", \"id\": \"sec-bin\", \"props\": {\"title\": \"Bin / Godown Allocation\", \"span\": 12, \"subtitle\": \"Pick the destination bin/godown. Stock balance updates immediately on confirmation.\"}, \"children\": [{\"type\": \"Form\", \"id\": \"form-bin\", \"props\": {\"submitLabel\": \"\"}, \"bindings\": {\"fields\": [{\"name\": \"godown_code\", \"label\": \"Godown\", \"type\": \"select\", \"required\": true, \"options\": [{\"label\": \"G1 — Main Stores (free 62%)\", \"value\": \"G1\"}, {\"label\": \"G2 — Packing Material Stores (free 41%)\", \"value\": \"G2\"}, {\"label\": \"G3 — Returns / Quarantine (free 88%)\", \"value\": \"G3\"}, {\"label\": \"G4 — FG Stores (free 35%)\", \"value\": \"G4\"}]}, {\"name\": \"bin_code\", \"label\": \"Bin / Rack\", \"type\": \"select\", \"required\": true, \"options\": [{\"label\": \"A-01 (free)\", \"value\": \"A-01\"}, {\"label\": \"A-02 (partial — 30%)\", \"value\": \"A-02\"}, {\"label\": \"A-03 (free)\", \"value\": \"A-03\"}, {\"label\": \"B-01 (full — assign next)\", \"value\": \"B-01\"}, {\"label\": \"B-02 (free)\", \"value\": \"B-02\"}, {\"label\": \"C-01 (free)\", \"value\": \"C-01\"}, {\"label\": \"C-02 (free)\", \"value\": \"C-02\"}]}, {\"name\": \"stack_pattern\", \"label\": \"Stacking Pattern\", \"type\": \"select\", \"options\": [{\"label\": \"Standard pallet (4 cases / layer × 5 layers)\", \"value\": \"STD_PALLET\"}, {\"label\": \"Bin stack (max 8 layers)\", \"value\": \"BIN_STACK\"}, {\"label\": \"Single layer (fragile)\", \"value\": \"SINGLE\"}]}, {\"name\": \"storage_condition\", \"label\": \"Storage Condition\", \"type\": \"select\", \"options\": [{\"label\": \"Ambient\", \"value\": \"AMBIENT\"}, {\"label\": \"Cool & Dry\", \"value\": \"COOL_DRY\"}, {\"label\": \"Quarantine — QC pending\", \"value\": \"QUARANTINE\"}]}]}}]}, {\"type\": \"Section\", \"id\": \"sec-damage\", \"props\": {\"title\": \"Damage / Short-Receipt Check\", \"span\": 12, \"subtitle\": \"Capture damaged or short items separately. They route to QC for vendor debit-note.\"}, \"children\": [{\"type\": \"Form\", \"id\": \"form-dmg\", \"props\": {\"submitLabel\": \"\"}, \"bindings\": {\"fields\": [{\"name\": \"damaged_qty\", \"label\": \"Damaged Quantity\", \"type\": \"number\", \"helperText\": \"Cases / bottles found damaged on unload. Photo evidence required.\"}, {\"name\": \"damage_reason\", \"label\": \"Damage Reason\", \"type\": \"select\", \"options\": [{\"label\": \"Transport damage (crushed / dented)\", \"value\": \"TRANSPORT\"}, {\"label\": \"Packing leak\", \"value\": \"LEAK\"}, {\"label\": \"Seal broken\", \"value\": \"SEAL_BROKEN\"}, {\"label\": \"Expired before receipt\", \"value\": \"EXPIRED\"}, {\"label\": \"Other (see notes)\", \"value\": \"OTHER\"}]}, {\"name\": \"short_qty\", \"label\": \"Short Quantity (vs invoice)\", \"type\": \"number\", \"helperText\": \"Triggers debit-note workflow against vendor\"}, {\"name\": \"damage_photo\", \"label\": \"Damage / Short-Receipt Photo\", \"type\": \"file\", \"accept\": \"image/*\"}, {\"name\": \"notes\", \"label\": \"Notes\", \"type\": \"textarea\", \"rows\": 3}]}}]}, {\"type\": \"Section\", \"id\": \"sec-confirm\", \"props\": {\"title\": \"Confirm Storage Complete\", \"span\": 12}, \"children\": [{\"type\": \"Form\", \"id\": \"form-cf\", \"props\": {\"submitLabel\": \"\"}, \"bindings\": {\"fields\": [{\"name\": \"supervisor_id\", \"label\": \"Supervisor (auto-fill)\", \"type\": \"text\", \"readOnly\": true}, {\"name\": \"start_ts\", \"label\": \"Unloading Start\", \"type\": \"datetime-local\"}, {\"name\": \"finish_ts\", \"label\": \"Unloading Finish\", \"type\": \"datetime-local\"}, {\"name\": \"seal_unlock_no\", \"label\": \"Seal # broken on unload\", \"type\": \"text\"}, {\"name\": \"grn_to_create\", \"label\": \"Create GRN now?\", \"type\": \"select\", \"required\": true, \"options\": [{\"label\": \"✓ Yes — auto-create GRN against PO\", \"value\": \"YES\"}, {\"label\": \"Later — supervisor will create from GRN page\", \"value\": \"NO\"}]}]}, \"props\": {}}, {\"type\": \"WorkflowActionButton\", \"id\": \"btn-fin\", \"props\": {\"action\": \"workflow.transition\", \"label\": \"Close Unloading — Stock Updated\", \"variant\": \"primary\"}}]}]}}',NULL,'2026-06-07 08:10:58',NULL,'2026-06-07 08:10:58'),
(7,7,1,'PUBLISHED','{\"kind\": \"list\", \"dataSource\": {\"entity\": \"GatePass\", \"select\": [\"id\", \"gp_number\", \"vehicle_no\", \"driver_name\", \"flow_variant_code\", \"current_step\", \"status\", \"source_party\", \"reference_no\", \"ordered_qty\", \"total_unloading_qty\", \"w1_weight_kg\", \"w2_weight_kg\", \"w3_weight_kg\", \"variance_reason\", \"manager_overrides_count\", \"updated_at\"], \"filter\": {\"field\": \"current_step\", \"op\": \"in\", \"value\": [\"QTY_PENDING_MANAGER\", \"WEIGHT_DIFF_PENDING_MANAGER\", \"PO_PENDING_MANAGER\", \"RETURN_PENDING_MANAGER\", \"QC_REJECTED\", \"REJECTED_BY_MANAGER\"]}, \"sort\": [{\"field\": \"updated_at\", \"dir\": \"desc\"}]}, \"columns\": [{\"field\": \"gp_number\", \"label\": \"GP #\", \"sortable\": true}, {\"field\": \"vehicle_no\", \"label\": \"Vehicle\", \"sortable\": true}, {\"field\": \"driver_name\", \"label\": \"Driver\", \"sortable\": true}, {\"field\": \"flow_variant_code\", \"label\": \"Flow\", \"sortable\": true, \"render\": \"badge\", \"colorMap\": {\"M10.TankerInbound\": \"blue\", \"M10.PackUnload\": \"blue\", \"M10.ReturnStockIn\": \"amber\", \"M10.TankerOutbound\": \"green\", \"M10.PackLoading\": \"green\", \"M10.FGLoading\": \"green\"}}, {\"field\": \"current_step\", \"label\": \"Awaiting\", \"sortable\": true, \"render\": \"badge\", \"colorMap\": {\"QTY_PENDING_MANAGER\": \"amber\", \"WEIGHT_DIFF_PENDING_MANAGER\": \"amber\", \"PO_PENDING_MANAGER\": \"amber\", \"RETURN_PENDING_MANAGER\": \"amber\", \"QC_REJECTED\": \"red\", \"REJECTED_BY_MANAGER\": \"red\"}}, {\"field\": \"source_party\", \"label\": \"From\", \"sortable\": true}, {\"field\": \"reference_no\", \"label\": \"Ref #\", \"sortable\": true}, {\"field\": \"w1_weight_kg\", \"label\": \"W1 (kg)\", \"render\": \"number\"}, {\"field\": \"w2_weight_kg\", \"label\": \"W2 (kg)\", \"render\": \"number\"}, {\"field\": \"w3_weight_kg\", \"label\": \"W3 (kg)\", \"render\": \"number\"}, {\"field\": \"total_unloading_qty\", \"label\": \"Unloaded\", \"render\": \"number\"}, {\"field\": \"manager_overrides_count\", \"label\": \"Overrides #\", \"render\": \"number\"}, {\"field\": \"variance_reason\", \"label\": \"Reason\"}, {\"field\": \"updated_at\", \"label\": \"Last Activity\", \"render\": \"datetime\", \"sortable\": true}], \"filters\": [{\"field\": \"flow_variant_code\", \"label\": \"Flow\", \"type\": \"multi-select\", \"options\": [\"M10.TankerInbound\", \"M10.PackUnload\", \"M10.ReturnStockIn\", \"M10.TankerOutbound\", \"M10.PackLoading\", \"M10.FGLoading\"]}, {\"field\": \"current_step\", \"label\": \"Awaiting\", \"type\": \"multi-select\", \"options\": [\"QTY_PENDING_MANAGER\", \"WEIGHT_DIFF_PENDING_MANAGER\", \"PO_PENDING_MANAGER\", \"RETURN_PENDING_MANAGER\", \"QC_REJECTED\", \"REJECTED_BY_MANAGER\"]}, {\"field\": \"_q\", \"label\": \"Search GP / Vehicle / Driver / Ref\", \"type\": \"text-contains\", \"applyTo\": [\"gp_number\", \"vehicle_no\", \"driver_name\", \"reference_no\", \"source_party\"]}], \"rowActions\": [{\"label\": \"✓ Approve\", \"action\": \"entity.update-field\", \"args\": {\"field\": \"current_step\", \"value\": \"QTY_RECONCILED\"}}, {\"label\": \"✗ Reject\", \"action\": \"entity.update-field\", \"args\": {\"field\": \"current_step\", \"value\": \"REJECTED_BY_MANAGER\"}}, {\"label\": \"🖨 Print\", \"action\": \"print.html\", \"args\": {\"kind\": \"gate-pass\"}}, {\"label\": \"Trail\", \"action\": \"page.open\", \"page\": \"aria:audit-log\"}], \"pagination\": {\"pageSize\": 25}}',NULL,'2026-06-07 08:10:58',NULL,'2026-06-07 08:10:58'),
