(703,318,1,'PUBLISHED','{\"schemaVersion\": \"1.0.0\", \"slug\": \"aria:reconciliation-form\", \"title\": \"Reconciliation Decision\", \"status\": \"published\", \"version\": 1, \"roles\": [\"Dispatch\", \"ParkingSecurity\", \"Manager\", \"TenantAdmin\"], \"dataSources\": [], \"streams\": [], \"layout\": {\"type\": \"Grid\", \"id\": \"root\", \"props\": {\"columns\": 12, \"gap\": 16}, \"children\": [{\"type\": \"Section\", \"id\": \"sec-context\", \"props\": {\"title\": \"Comparison\", \"span\": 12, \"subtitle\": \"System computes the delta; within ±0.25% auto-passes, beyond requires manager.\"}, \"children\": [{\"type\": \"Form\", \"id\": \"form-rec\", \"props\": {\"submitLabel\": \"\"}, \"bindings\": {\"fields\": [{\"name\": \"gp_number\", \"label\": \"Gate Pass #\", \"type\": \"text\", \"required\": true, \"readOnly\": true}, {\"name\": \"ordered_qty\", \"label\": \"Ordered Qty (kg) — from OrderApp / PO\", \"type\": \"number\", \"readOnly\": true}, {\"name\": \"unloaded_qty\", \"label\": \"Unloaded Qty (kg) — from supervisor\", \"type\": \"number\", \"readOnly\": true}, {\"name\": \"delta_kg\", \"label\": \"Delta (kg) — auto\", \"type\": \"number\", \"readOnly\": true}, {\"name\": \"delta_pct\", \"label\": \"Delta % — auto\", \"type\": \"number\", \"readOnly\": true}, {\"name\": \"within_tolerance\", \"label\": \"Within Tolerance?\", \"type\": \"select\", \"required\": true, \"options\": [{\"label\": \"YES — proceed to final weighment\", \"value\": \"YES\"}, {\"label\": \"NO — route to manager for approval\", \"value\": \"NO\"}]}, {\"name\": \"reason\", \"label\": \"Reason / Notes\", \"type\": \"textarea\", \"rows\": 3}]}}]}, {\"type\": \"Section\", \"id\": \"sec-submit\", \"props\": {\"span\": 12}, \"children\": [{\"type\": \"WorkflowActionButton\", \"id\": \"btn-rec\", \"props\": {\"action\": \"workflow.transition\", \"label\": \"Submit Reconciliation\", \"variant\": \"primary\"}}]}]}}',NULL,NULL,NULL,'2026-06-26 17:32:25'),
(704,319,1,'PUBLISHED','{\"schemaVersion\": \"1.0.0\", \"slug\": \"aria:gate-pass-closure-form\", \"title\": \"Gate Pass Closure — Final Checks\", \"status\": \"published\", \"version\": 1, \"roles\": [\"FrontGate\", \"Dispatch\", \"Manager\", \"TenantAdmin\"], \"dataSources\": [], \"streams\": [], \"layout\": {\"type\": \"Grid\", \"id\": \"root\", \"props\": {\"columns\": 12, \"gap\": 16}, \"children\": [{\"type\": \"Section\", \"id\": \"sec-summary\", \"props\": {\"title\": \"Vehicle Summary (auto-fill from workflow)\", \"span\": 12}, \"children\": [{\"type\": \"Form\", \"id\": \"form-sum\", \"props\": {\"submitLabel\": \"\"}, \"bindings\": {\"fields\": [{\"name\": \"gp_number\", \"label\": \"Gate Pass #\", \"type\": \"text\", \"readOnly\": true}, {\"name\": \"vehicle_no\", \"label\": \"Vehicle\", \"type\": \"text\", \"readOnly\": true}, {\"name\": \"flow_summary\", \"label\": \"Flow Summary\", \"type\": \"text\", \"readOnly\": true, \"helperText\": \"e.g. Tanker Unloading · 9,120 kg into TANK-1 · W2-W3 diff 0 kg · Sealed\"}, {\"name\": \"total_time_min\", \"label\": \"Total Time on Site (minutes)\", \"type\": \"number\", \"readOnly\": true}]}}]}, {\"type\": \"Section\", \"id\": \"sec-checks\", \"props\": {\"title\": \"Final Gate Checks\", \"span\": 12, \"subtitle\": \"All checks must be ✓ or status will be HOLD\"}, \"children\": [{\"type\": \"Form\", \"id\": \"form-chk\", \"props\": {\"submitLabel\": \"\"}, \"bindings\": {\"fields\": [{\"name\": \"seal_verified\", \"label\": \"Seal verified at gate\", \"type\": \"select\", \"required\": true, \"options\": [{\"label\": \"✓ Number matches (system-generated)\", \"value\": \"MATCHED\"}, {\"label\": \"✗ Mismatch — hard block\", \"value\": \"MISMATCH\"}, {\"label\": \"N/A (no seal flow)\", \"value\": \"NA\"}]}, {\"name\": \"qc_clearance\", \"label\": \"QC clearance\", \"type\": \"select\", \"required\": true, \"options\": [{\"label\": \"✓ Approved\", \"value\": \"APPROVED\"}, {\"label\": \"✗ Rejected\", \"value\": \"REJECTED\"}]}, {\"name\": \"weighment_verified\", \"label\": \"Weighment verified (W1/W2/W3)\", \"type\": \"select\", \"required\": true, \"options\": [{\"label\": \"✓ All within tolerance\", \"value\": \"OK\"}, {\"label\": \"⚠ Manager-approved variance\", \"value\": \"MGR_APPROVED\"}, {\"label\": \"✗ Pending\", \"value\": \"PENDING\"}]}, {\"name\": \"order_recon_done\", \"label\": \"Order vs Unloaded reconciled\", \"type\": \"select\", \"required\": true, \"options\": [{\"label\": \"✓ Yes — within tolerance\", \"value\": \"OK\"}, {\"label\": \"⚠ Manager-approved discrepancy\", \"value\": \"MGR_APPROVED\"}, {\"label\": \"✗ No\", \"value\": \"NO\"}]}, {\"name\": \"within_tolerance\", \"label\": \"All checks clear?\", \"type\": \"select\", \"required\": true, \"options\": [{\"label\": \"YES — release vehicle\", \"value\": \"YES\"}, {\"label\": \"NO — route to manager\", \"value\": \"NO\"}]}]}}]}, {\"type\": \"Section\", \"id\": \"sec-submit\", \"props\": {\"span\": 12}, \"children\": [{\"type\": \"WorkflowActionButton\", \"id\": \"btn-close\", \"props\": {\"action\": \"workflow.transition\", \"label\": \"Close Gate Pass — Release Vehicle\", \"variant\": \"primary\"}}]}]}}',NULL,NULL,NULL,'2026-06-26 17:32:25'),
