(737,359,1,'PUBLISHED','{\"schemaVersion\": 2, \"kind\": \"list\", \"title\": \"AI Agent Promotions\", \"entity\": \"AiAgentPromotion\", \"dataSource\": {\"type\": \"entity\", \"entity\": \"AiAgentPromotion\"}, \"columns\": [{\"field\": \"approved_at\", \"label\": \"When\", \"sortable\": true}, {\"field\": \"agent_id\", \"label\": \"Agent\"}, {\"field\": \"from_mode\", \"label\": \"From\", \"render\": \"pill\", \"colorMap\": {\"SHADOW\": \"grey\", \"SUPERVISED\": \"blue\", \"GUARDED\": \"amber\", \"AUTONOMOUS\": \"green\", \"RETIRED\": \"red\"}}, {\"field\": \"to_mode\", \"label\": \"To\", \"render\": \"pill\", \"colorMap\": {\"SHADOW\": \"grey\", \"SUPERVISED\": \"blue\", \"GUARDED\": \"amber\", \"AUTONOMOUS\": \"green\", \"RETIRED\": \"red\"}}, {\"field\": \"approved_by\", \"label\": \"Approved By\"}, {\"field\": \"reason\", \"label\": \"Reason\"}], \"defaultSort\": {\"field\": \"approved_at\", \"dir\": \"desc\"}, \"pageSize\": 50}','V83 — AI agent promotions log','2026-07-11 06:32:26',NULL,'2026-07-11 06:32:26'),
(738,360,1,'PUBLISHED','{\"schemaVersion\": 2, \"kind\": \"layout\", \"title\": \"AI Kill Switch\", \"layout\": [{\"kind\": \"Markdown\", \"props\": {\"severity\": \"error\", \"content\": \"## Emergency stop — retire every AI agent\\n\\nPressing the button below sets every agent\'s `mode` to `RETIRED` and marks every binding as `active=false`. No agent will fire again until an operator explicitly re-enables it from the AI Agents page. Use this only if agents are producing dangerous outputs or the plant is in an unsafe state.\\n\"}}, {\"kind\": \"WorkflowActionButton\", \"props\": {\"label\": \"RETIRE ALL AGENTS\", \"severity\": \"error\", \"confirm\": {\"title\": \"Retire every AI agent?\", \"message\": \"This will immediately stop every SHADOW / SUPERVISED / GUARDED / AUTONOMOUS agent. This is reversible but requires re-promotion.\"}, \"action\": {\"kind\": \"workflow.transition\", \"workflowCode\": \"AI.KillSwitch\", \"toState\": \"RETIRED\"}}}, {\"kind\": \"Section\", \"props\": {\"title\": \"Currently running agents by mode\", \"subtitle\": \"Everything not already RETIRED will be stopped.\"}}, {\"kind\": \"KanbanView\", \"props\": {\"title\": \"Agents by mode\", \"dataSource\": {\"type\": \"entity\", \"entity\": \"AiAgent\", \"select\": [\"id\", \"code\", \"display_name\", \"category\", \"mode\", \"model\", \"status\"]}, \"groupBy\": \"mode\", \"pageSize\": 200, \"columns\": [{\"value\": \"SHADOW\", \"label\": \"Shadow\", \"color\": \"grey\"}, {\"value\": \"SUPERVISED\", \"label\": \"Supervised\", \"color\": \"blue\"}, {\"value\": \"GUARDED\", \"label\": \"Guarded\", \"color\": \"amber\"}, {\"value\": \"AUTONOMOUS\", \"label\": \"Autonomous\", \"color\": \"green\"}, {\"value\": \"RETIRED\", \"label\": \"Retired\", \"color\": \"red\"}], \"card\": {\"title\": \"{display_name}\", \"subtitle\": \"{code} · {model}\", \"badges\": [\"category\", \"status\"]}}}]}','V83 — AI kill switch layout','2026-07-11 06:32:26',NULL,'2026-07-11 06:32:26'),
(739,361,1,'PUBLISHED','{\"schemaVersion\": 2, \"kind\": \"list\", \"title\": \"Master Table Inventory\", \"dataSource\": {\"type\": \"entity\", \"entity\": \"MasterTableInventory\", \"select\": [\"table_name\", \"entity_code\", \"category\", \"display_name\", \"page_count\", \"workflow_count\", \"last_write_at\", \"writes_7d\", \"row_count\"]}, \"pageSize\": 100, \"defaultSort\": {\"by\": \"last_write_at\", \"dir\": \"desc\"}, \"columns\": [{\"field\": \"table_name\", \"label\": \"Table\", \"sortable\": true, \"filterable\": true, \"searchable\": true}, {\"field\": \"entity_code\", \"label\": \"Entity Code\", \"sortable\": true, \"filterable\": true, \"searchable\": true}, {\"field\": \"category\", \"label\": \"Category\", \"render\": \"pill\", \"colorMap\": {\"M0\": \"grey\", \"M5\": \"blue\", \"M6\": \"green\", \"M7\": \"purple\", \"M10\": \"amber\", \"M11\": \"teal\"}}, {\"field\": \"display_name\", \"label\": \"Display Name\", \"sortable\": true, \"searchable\": true}, {\"field\": \"page_count\", \"label\": \"Pages\", \"sortable\": true, \"align\": \"right\"}, {\"field\": \"workflow_count\", \"label\": \"Workflows\", \"sortable\": true, \"align\": \"right\"}, {\"field\": \"writes_7d\", \"label\": \"Writes (7d)\", \"render\": \"delta\", \"align\": \"right\"}, {\"field\": \"last_write_at\", \"label\": \"Last Write\", \"render\": \"datetime\", \"sortable\": true}, {\"field\": \"row_count\", \"label\": \"Rows (est.)\", \"sortable\": true, \"align\": \"right\"}], \"filters\": [{\"field\": \"category\", \"kind\": \"select\", \"options\": [\"M0\", \"M5\", \"M6\", \"M7\", \"M10\", \"M11\"]}, {\"field\": \"page_count\", \"kind\": \"number\", \"label\": \"Min pages\"}, {\"field\": \"workflow_count\", \"kind\": \"number\", \"label\": \"Min workflows\"}]}','V85 — master table inventory flagship list','2026-07-11 06:32:26',NULL,'2026-07-11 06:32:26'),
(740,362,1,'PUBLISHED','{\"schemaVersion\": 2, \"kind\": \"layout\", \"title\": \"Coverage Matrix\", \"layout\": [{\"kind\": \"Section\", \"props\": {\"title\": \"Test coverage by entity\", \"subtitle\": \"Every entity_registry code and whether any Playwright test currently exercises it.\"}}, {\"kind\": \"KpiGrid\", \"props\": {\"kpis\": [{\"label\": \"Total entities\", \"sql\": \"SELECT COUNT(*) FROM entity_registry\"}, {\"label\": \"Entities with a Playwright test\", \"sql\": \"SELECT COUNT(DISTINCT er.code) FROM entity_registry er WHERE EXISTS (SELECT 1 FROM m0_test_coverage tc WHERE tc.entity_code = er.code)\"}, {\"label\": \"Coverage %\", \"render\": \"percent\", \"sql\": \"SELECT ROUND(100 * (SELECT COUNT(DISTINCT er.code) FROM entity_registry er WHERE EXISTS (SELECT 1 FROM m0_test_coverage tc WHERE tc.entity_code = er.code)) / GREATEST(1,(SELECT COUNT(*) FROM entity_registry)), 1)\"}]}}, {\"kind\": \"Section\", \"props\": {\"title\": \"Untested entities\", \"subtitle\": \"Entities with zero test-agent coverage. Every row here is a gap.\"}}, {\"kind\": \"ListView\", \"props\": {\"dataSource\": {\"type\": \"sql\", \"sql\": \"SELECT er.code AS entity_code, er.display_name, er.category, er.table_name FROM entity_registry er WHERE NOT EXISTS (SELECT 1 FROM m0_test_coverage tc WHERE tc.entity_code = er.code) ORDER BY er.category, er.code\"}, \"columns\": [{\"field\": \"entity_code\", \"label\": \"Entity\"}, {\"field\": \"display_name\", \"label\": \"Display Name\"}, {\"field\": \"category\", \"label\": \"Category\", \"render\": \"pill\"}, {\"field\": \"table_name\", \"label\": \"Table\"}], \"pageSize\": 50}}, {\"kind\": \"Section\", \"props\": {\"title\": \"Page-workflow bindings health\", \"subtitle\": \"Pages that reference an entity but have no workflow transition writing to them. These are pages where users can look but nothing can move.\"}}, {\"kind\": \"KpiGrid\", \"props\": {\"kpis\": [{\"label\": \"Total published pages\", \"sql\": \"SELECT COUNT(*) FROM page_definition WHERE tenant_id=1 AND status=\'PUBLISHED\'\"}, {\"label\": \"Pages with no workflow binding\", \"sql\": \"SELECT COUNT(*) FROM page_definition pd WHERE pd.tenant_id=1 AND pd.status=\'PUBLISHED\' AND NOT EXISTS (SELECT 1 FROM workflow_definition wd WHERE wd.tenant_id=1 AND wd.status=\'PUBLISHED\' AND JSON_SEARCH(wd.body_json, \'one\', pd.code, NULL, \'$**.pageCode\') IS NOT NULL)\"}, {\"label\": \"Pages driven by a workflow\", \"sql\": \"SELECT COUNT(DISTINCT pd.code) FROM page_definition pd JOIN workflow_definition wd ON wd.tenant_id=1 AND wd.status=\'PUBLISHED\' AND JSON_SEARCH(wd.body_json, \'one\', pd.code, NULL, \'$**.pageCode\') IS NOT NULL WHERE pd.tenant_id=1 AND pd.status=\'PUBLISHED\'\"}]}}]}','V85 — coverage matrix dashboard','2026-07-11 06:32:26',NULL,'2026-07-11 06:32:26'),
(741,363,1,'PUBLISHED','{\"schemaVersion\": 2, \"kind\": \"list\", \"title\": \"Page Catalog\", \"dataSource\": {\"type\": \"sql\", \"sql\": \"SELECT pd.id, pd.code, pd.title, pd.category, pd.status, pv.version AS current_version, pv.status AS version_status, pd.updated_at FROM page_definition pd LEFT JOIN page_version pv ON pv.id = pd.current_version_id WHERE pd.tenant_id = 1\"}, \"pageSize\": 100, \"defaultSort\": {\"by\": \"updated_at\", \"dir\": \"desc\"}, \"columns\": [{\"field\": \"code\", \"label\": \"Page Code\", \"sortable\": true, \"searchable\": true, \"filterable\": true}, {\"field\": \"title\", \"label\": \"Title\", \"sortable\": true, \"searchable\": true}, {\"field\": \"category\", \"label\": \"Category\", \"render\": \"pill\", \"colorMap\": {\"M0\": \"grey\", \"M5\": \"blue\", \"M6\": \"green\", \"M7\": \"purple\", \"M10\": \"amber\", \"M11\": \"teal\", \"Dashboard\": \"indigo\"}}, {\"field\": \"current_version\", \"label\": \"Version\", \"align\": \"right\"}, {\"field\": \"version_status\", \"label\": \"Version Status\", \"render\": \"pill\", \"colorMap\": {\"PUBLISHED\": \"green\", \"DRAFT\": \"amber\", \"DEPRECATED\": \"red\"}}, {\"field\": \"status\", \"label\": \"Page Status\", \"render\": \"pill\", \"colorMap\": {\"PUBLISHED\": \"green\", \"DRAFT\": \"amber\", \"ARCHIVED\": \"red\"}}, {\"field\": \"updated_at\", \"label\": \"Last Modified\", \"render\": \"datetime\", \"sortable\": true}], \"filters\": [{\"field\": \"category\", \"kind\": \"select\", \"options\": [\"M0\", \"M5\", \"M6\", \"M7\", \"M10\", \"M11\", \"Dashboard\"]}, {\"field\": \"status\", \"kind\": \"select\", \"options\": [\"PUBLISHED\", \"DRAFT\", \"ARCHIVED\"]}]}','V85 — page catalog','2026-07-11 06:32:26',NULL,'2026-07-11 06:32:26'),
(742,364,1,'PUBLISHED','{\"schemaVersion\": 2, \"kind\": \"list\", \"title\": \"Workflow Catalog\", \"dataSource\": {\"type\": \"sql\", \"sql\": \"SELECT wd.id, wd.code, wd.version, wd.status, COALESCE(JSON_LENGTH(JSON_EXTRACT(wd.body_json, \'$.states\')),0) AS state_count, COALESCE(JSON_LENGTH(JSON_EXTRACT(wd.body_json, \'$.transitions\')),0) AS transition_count, wd.created_at FROM workflow_definition wd WHERE wd.tenant_id = 1\"}, \"pageSize\": 100, \"defaultSort\": {\"by\": \"code\", \"dir\": \"asc\"}, \"columns\": [{\"field\": \"code\", \"label\": \"Workflow Code\", \"sortable\": true, \"searchable\": true, \"filterable\": true}, {\"field\": \"version\", \"label\": \"Version\", \"align\": \"right\", \"sortable\": true}, {\"field\": \"status\", \"label\": \"Status\", \"render\": \"pill\", \"colorMap\": {\"PUBLISHED\": \"green\", \"DRAFT\": \"amber\", \"DEPRECATED\": \"red\"}}, {\"field\": \"state_count\", \"label\": \"States\", \"align\": \"right\", \"sortable\": true}, {\"field\": \"transition_count\", \"label\": \"Transitions\", \"align\": \"right\", \"sortable\": true}, {\"field\": \"created_at\", \"label\": \"Created\", \"render\": \"datetime\", \"sortable\": true}], \"filters\": [{\"field\": \"status\", \"kind\": \"select\", \"options\": [\"PUBLISHED\", \"DRAFT\", \"DEPRECATED\"]}]}','V85 — workflow catalog','2026-07-11 06:32:26',NULL,'2026-07-11 06:32:26');
INSERT IGNORE INTO `page_version` (`id`, `page_id`, `version`, `status`, `body_json`, `rationale`, `published_at`, `published_by`, `created_at`) VALUES (743,365,1,'PUBLISHED','{\"kind\": \"layout\", \"schemaVersion\": 2, \"dataSources\": [{\"id\": \"dispatchQueue\", \"kind\": \"rest\", \"method\": \"GET\", \"url\": \"/api/workflow/queue/Dispatch\"}], \"layout\": [{\"kind\": \"Section\", \"title\": \"Dispatch Queue (Open)\", \"fields\": [{\"kind\": \"WorkflowQueueList\", \"persona\": \"Dispatch\", \"dataSource\": \"dispatchQueue\", \"pageSize\": 25, \"cardFields\": [\"vehicleNo\", \"gpNumber\", \"flowVariant\", \"currentState\"]}]}, {\"kind\": \"Section\", \"title\": \"Vehicle & Dispatch Details\", \"fields\": [{\"kind\": \"FormField\", \"type\": \"select\", \"name\": \"vehicleNo\", \"label\": \"Vehicle Number\", \"required\": true, \"placeholder\": \"Select vehicle awaiting dispatch entry\", \"optionsSource\": {\"type\": \"entity\", \"entity\": \"GatePass\", \"lookupType\": \"vehicleNumbers\", \"valueField\": \"vehicle_no\", \"labelField\": \"vehicle_no\"}, \"onChangeFill\": {\"flowVariantCode\": \"flow_variant_code\", \"loadingType\": \"loading_type\", \"instanceId\": \"workflow_instance_id\"}}, {\"kind\": \"FormField\", \"type\": \"text\", \"name\": \"flowVariantCode\", \"label\": \"Flow Variant\", \"disabled\": true}, {\"kind\": \"FormField\", \"type\": \"text\", \"name\": \"loadingType\", \"label\": \"Loading Type\", \"disabled\": true}, {\"kind\": \"FormField\", \"type\": \"text\", \"name\": \"instanceId\", \"label\": \"Workflow Instance\", \"disabled\": true}, {\"kind\": \"FormField\", \"type\": \"select\", \"name\": \"ownershipType\", \"label\": \"Ownership\", \"options\": [\"OWN VEHICLE\", \"HIRED VEHICLE\"]}, {\"kind\": \"FormField\", \"type\": \"text\", \"name\": \"driverName\", \"label\": \"Driver Name\"}, {\"kind\": \"FormField\", \"type\": \"text\", \"name\": \"driverPhone\", \"label\": \"Driver Contact\"}, {\"kind\": \"FormField\", \"type\": \"text\", \"name\": \"brokerName\", \"label\": \"Broker Details\", \"visibleWhen\": \"#form.flowVariantCode == \'M10.TankerOutbound\'\"}, {\"kind\": \"FormField\", \"type\": \"text\", \"name\": \"invoiceNo\", \"label\": \"Invoice No\", \"visibleWhen\": \"#form.flowVariantCode == \'M10.TankerOutbound\'\"}, {\"kind\": \"FormField\", \"type\": \"number\", \"name\": \"invoiceQty\", \"label\": \"Invoice Qty\", \"visibleWhen\": \"#form.flowVariantCode == \'M10.TankerOutbound\'\"}, {\"kind\": \"FormField\", \"type\": \"text\", \"name\": \"vendorName\", \"label\": \"Vendor Details\", \"visibleWhen\": \"#form.flowVariantCode == \'M10.TankerOutbound\'\"}, {\"kind\": \"FormField\", \"type\": \"text\", \"name\": \"oilRmItem\", \"label\": \"Oil RM Details\", \"visibleWhen\": \"#form.flowVariantCode == \'M10.TankerOutbound\'\"}, {\"kind\": \"FormField\", \"type\": \"text\", \"name\": \"tankerNo\", \"label\": \"Tanker Number\", \"visibleWhen\": \"#form.flowVariantCode == \'M10.TankerOutbound\'\"}, {\"kind\": \"FormField\", \"type\": \"select\", \"name\": \"poVerified\", \"label\": \"PO Verified\", \"options\": [\"YES\", \"NO - MANAGER APPROVAL\"], \"visibleWhen\": \"#form.flowVariantCode == \'M10.TankerOutbound\'\"}, {\"kind\": \"FormField\", \"type\": \"text\", \"name\": \"poOverrideReason\", \"label\": \"Reason (if PO not verified)\", \"visibleWhen\": \"#form.flowVariantCode == \'M10.TankerOutbound\' && #form.poVerified != \'YES\'\", \"requiredWhen\": \"#form.flowVariantCode == \'M10.TankerOutbound\' && #form.poVerified != \'YES\'\"}, {\"kind\": \"FormField\", \"type\": \"text\", \"name\": \"dispatchOfficerName\", \"label\": \"Dispatch Front Officer Name\", \"visibleWhen\": \"#form.flowVariantCode == \'M10.TankerOutbound\'\"}, {\"kind\": \"FormField\", \"type\": \"text\", \"name\": \"transportName\", \"label\": \"Transport Name\", \"visibleWhen\": \"#form.flowVariantCode == \'M10.PackLoading\' || #form.flowVariantCode == \'M10.FGLoading\'\"}, {\"kind\": \"FormField\", \"type\": \"textarea