(763,376,2,'PUBLISHED','{\"schemaVersion\": 2, \"kind\": \"list\", \"title\": \"AI Credentials\", \"description\": \"Point EARMS at your own AI model. Register the provider, endpoint (e.g. http://localhost:1234 for LM Studio, or your on-prem Ollama URL), model name, and optional API key. Press Test on any row to verify the connection.\", \"dataSource\": {\"type\": \"entity\", \"entity\": \"TenantAiCredential\", \"select\": [\"id\", \"tenant_id\", \"provider\", \"model\", \"endpoint\", \"max_tokens_per_day\", \"cost_cap_paise_per_day\", \"kill_switch\", \"updated_at\"]}, \"columns\": [{\"field\": \"provider\", \"label\": \"Provider\", \"render\": \"pill\", \"colorMap\": {\"ollama-local\": \"grey\", \"ollama-hosted\": \"teal\", \"openai\": \"green\", \"openai-compatible\": \"blue\"}}, {\"field\": \"model\", \"label\": \"Model\"}, {\"field\": \"endpoint\", \"label\": \"Endpoint\"}, {\"field\": \"max_tokens_per_day\", \"label\": \"Tokens/Day\", \"align\": \"right\"}, {\"field\": \"cost_cap_paise_per_day\", \"label\": \"Cost Cap (paise)\", \"align\": \"right\"}, {\"field\": \"kill_switch\", \"label\": \"Kill Switch\", \"render\": \"pill\", \"colorMap\": {\"true\": \"red\", \"false\": \"green\"}}, {\"field\": \"updated_at\", \"label\": \"Updated\"}], \"actions\": [{\"code\": \"create\", \"label\": \"Add Credential\", \"style\": \"primary\"}, {\"code\": \"edit\", \"label\": \"Edit\"}, {\"code\": \"delete\", \"label\": \"Delete\", \"style\": \"danger\"}], \"rowActions\": [{\"code\": \"test\", \"label\": \"Test\", \"kind\": \"external.api.call\", \"method\": \"POST\", \"url\": \"/api/ai/credentials/{id}/test\", \"successToast\": \"Connection OK ({latencyMs} ms) — model {model} on {endpoint}\", \"errorToast\": \"Test failed: {message}\"}], \"pageSize\": 25, \"notice\": \"Supported providers: ollama-local, ollama-hosted, openai, openai-compatible. Keys are stored on the tenant database only.\"}','V91 — add Test row action + widen provider list','2026-07-11 11:52:53',NULL,'2026