-- ═══════════════════════════════════════════════════════════════════
-- V2 — the Aria product catalogue (tenant_id = -1).
--
-- Structure only: pages, workflows, entity/field definitions, the element
-- catalogue, print templates, AI agents. No business data, no branding, no
-- credentials — those are tenant-owned and never ship in the product.
--
-- Every tenant INHERITS this. Resolution is "tenant row wins, else global":
--     WHERE tenant_id IN (:tid, -1) ORDER BY tenant_id DESC LIMIT 1
-- so a customer owns only what they actually changed, and a fix here reaches
-- every customer without touching a single one of their rows.
--
-- A fresh install therefore has ZERO tenants. Onboarding creates them and
-- allocates the id — which is what makes the next customer a payload rather
-- than a project.
--
-- INSERT IGNORE throughout, so replaying this is a no-op.
-- ═══════════════════════════════════════════════════════════════════

SET FOREIGN_KEY_CHECKS = 0;
LOCK TABLES `entity_registry` WRITE;
set autocommit=0;
UNLOCK TABLES;
commit;
LOCK TABLES `entity_field_registry` WRITE;
set autocommit=0;
UNLOCK TABLES;
commit;
LOCK TABLES `page_definition` WRITE;
set autocommit=0;
UNLOCK TABLES;
commit;
LOCK TABLES `page_version` WRITE;
set autocommit=0;
UNLOCK TABLES;
commit;
LOCK TABLES `workflow_definition` WRITE;
set autocommit=0;
UNLOCK TABLES;
commit;
LOCK TABLES `page_element_catalog` WRITE;
set autocommit=0;
UNLOCK TABLES;
commit;
LOCK TABLES `print_template` WRITE;
set autocommit=0;
UNLOCK TABLES;
commit;
LOCK TABLES `ai_agent` WRITE;
set autocommit=0;
UNLOCK TABLES;
commit;

SET FOREIGN_KEY_CHECKS = 1;
